            "Planos axial, coronal e sagital organizam cortes e reconstruções. Localização exige orientação, lateralidade e referências anatômicas. Seguir uma estrutura em cortes consecutivos reduz confusão entre regiões próximas; uma imagem isolada pode ocultar continuidade e sobreposição.",
