          {
            "tag": "REFERÊNCIA",
            "title": "Ética e Estágio em Radiologia",
            "text": "DANCE, D. R. et al. (eds.). Diagnostic Radiology Physics: A Handbook for Teachers and Students. IAEA, 2014. Tema de estudo: Formação prática reúne responsabilidade, identificação, privacidade e comunicação acessível. Registro de estágio descreve participação, observações e aprendizagem. Imagens e dados de pessoas exigem tratamento apropriado ao ambiente de ensino e serviço."
          },
          {
            "tag": "REFERÊNCIA",
            "title": "Pesquisa e Evidências em Radiologia",
            "text": "DANCE, D. R. et al. (eds.). Diagnostic Radiology Physics: A Handbook for Teachers and Students. IAEA, 2014. Tema de estudo: Uma pergunta de pesquisa define população, técnica, comparação e desfecho quando pertinente. Qualidade de imagem pode ser avaliada por medidas físicas e observadores, com critérios distintos. Comparações exigem condições equivalentes e análise da variabilidade."
          }
